ALTER TABLE usuarios ADD COLUMN foto VARCHAR(255) NULL AFTER curso;
ALTER TABLE chat_mensagens ADD COLUMN sala_id INT UNSIGNED NULL AFTER usuario_id;
CREATE TABLE IF NOT EXISTS chat_salas(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,nome VARCHAR(120) NOT NULL,descricao VARCHAR(255),criado_por INT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(criado_por) REFERENCES usuarios(id));
CREATE TABLE IF NOT EXISTS notificacoes(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,usuario_id INT UNSIGNED NOT NULL,titulo VARCHAR(150) NOT NULL,mensagem VARCHAR(500) NOT NULL,link VARCHAR(255),lida TINYINT(1) NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(usuario_id) REFERENCES usuarios(id) ON DELETE CASCADE,INDEX(usuario_id,lida));
CREATE TABLE IF NOT EXISTS reservas(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,usuario_id INT UNSIGNED NOT NULL,livro_id INT UNSIGNED NOT NULL,status ENUM('ativa','atendida','cancelada') NOT NULL DEFAULT 'ativa',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(usuario_id) REFERENCES usuarios(id) ON DELETE CASCADE,FOREIGN KEY(livro_id) REFERENCES livros(id) ON DELETE CASCADE,UNIQUE KEY reserva_ativa(usuario_id,livro_id,status));
CREATE TABLE IF NOT EXISTS favoritos(usuario_id INT UNSIGNED NOT NULL,livro_id INT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(usuario_id,livro_id),FOREIGN KEY(usuario_id) REFERENCES usuarios(id) ON DELETE CASCADE,FOREIGN KEY(livro_id) REFERENCES livros(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS avaliacoes(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,usuario_id INT UNSIGNED NOT NULL,livro_id INT UNSIGNED NOT NULL,nota TINYINT UNSIGNED NOT NULL,comentario VARCHAR(500),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(usuario_id) REFERENCES usuarios(id) ON DELETE CASCADE,FOREIGN KEY(livro_id) REFERENCES livros(id) ON DELETE CASCADE,UNIQUE KEY avaliacao_unica(usuario_id,livro_id));
CREATE TABLE IF NOT EXISTS leitura_progresso(usuario_id INT UNSIGNED NOT NULL,livro_id INT UNSIGNED NOT NULL,aberturas INT UNSIGNED NOT NULL DEFAULT 1,ultima_leitura TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(usuario_id,livro_id),FOREIGN KEY(usuario_id) REFERENCES usuarios(id) ON DELETE CASCADE,FOREIGN KEY(livro_id) REFERENCES livros(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS quizzes(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,titulo VARCHAR(255) NOT NULL,disciplina VARCHAR(120) NOT NULL,descricao TEXT,criado_por INT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(criado_por) REFERENCES usuarios(id));
CREATE TABLE IF NOT EXISTS quiz_perguntas(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,quiz_id INT UNSIGNED NOT NULL,pergunta TEXT NOT NULL,alternativa_a VARCHAR(500) NOT NULL,alternativa_b VARCHAR(500) NOT NULL,alternativa_c VARCHAR(500) NOT NULL,alternativa_d VARCHAR(500) NOT NULL,correta ENUM('a','b','c','d') NOT NULL,FOREIGN KEY(quiz_id) REFERENCES quizzes(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS quiz_respostas(usuario_id INT UNSIGNED NOT NULL,pergunta_id INT UNSIGNED NOT NULL,resposta ENUM('a','b','c','d') NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(usuario_id,pergunta_id),FOREIGN KEY(usuario_id) REFERENCES usuarios(id) ON DELETE CASCADE,FOREIGN KEY(pergunta_id) REFERENCES quiz_perguntas(id) ON DELETE CASCADE);


-- BookNet: embaralhamento das alternativas dos quizzes por aluno
CREATE TABLE IF NOT EXISTS quiz_ordens_alternativas (
 usuario_id INT UNSIGNED NOT NULL,
 quiz_id INT UNSIGNED NOT NULL,
 pergunta_id INT UNSIGNED NOT NULL,
 ordem CHAR(4) NOT NULL,
 PRIMARY KEY (usuario_id, pergunta_id),
 FOREIGN KEY (usuario_id) REFERENCES usuarios(id) ON DELETE CASCADE,
 FOREIGN KEY (quiz_id) REFERENCES quizzes(id) ON DELETE CASCADE,
 FOREIGN KEY (pergunta_id) REFERENCES quiz_perguntas(id) ON DELETE CASCADE
);
